    /// <summary>
    /// Checks if a specific pseudo-class has been set on the element.<br/>
    /// 
    /// @param pseudo_class The name of the pseudo-class to check for.<br/>
    /// @return True if the pseudo-class is set on the element, false if not.<br/>
    /// </summary>
    /// <remarks>C++: <c>bool Rml::Element::IsPseudoClassSet(const String&amp; pseudo_class) const</c></remarks>
    public bool IsPseudoClassSet(string pseudoClass)
    {
        scoped Utf8StringMarshaller.ManagedToUnmanagedIn pseudoClass_m = new();
        pseudoClass_m.FromManaged(pseudoClass, stackalloc byte[Utf8StringMarshaller.ManagedToUnmanagedIn.BufferSize]);
        try
        {
            return NativeMethods.RmlElement_IsPseudoClassSet(Handle, pseudoClass_m.ToUnmanaged()) != 0;
        }
        finally
        {
            pseudoClass_m.Free();
        }
    }

    /// <summary>
    /// Checks if a complete set of pseudo-classes are set on the element.<br/>
    /// 
    /// @param pseudo_classes The list of pseudo-classes to check for.<br/>
    /// @return True if all the pseudo-classes are set, false if not.<br/>
    /// </summary>
    /// <remarks>C++: <c>bool Rml::Element::ArePseudoClassesSet(const StringList&amp; pseudo_classes) const</c></remarks>
    public bool ArePseudoClassesSet(IEnumerable<string> pseudoClasses)
    {
        string[] pseudoClasses_s = [.. pseudoClasses];
        byte** pseudoClasses_p = (byte**)NativeMemory.AllocZeroed((nuint)pseudoClasses_s.Length, (nuint)sizeof(nint));
        for (int i = 0; i < pseudoClasses_s.Length; i++) { pseudoClasses_p[i] = Utf8StringMarshaller.ConvertToUnmanaged(pseudoClasses_s[i]); }
        try
        {
            return NativeMethods.RmlElement_ArePseudoClassesSet(Handle, new RmlArray((nint)pseudoClasses_p, (nuint)pseudoClasses_s.Length)) != 0;
        }
        finally
        {
            for (int i = 0; i < pseudoClasses_s.Length; i++) { Utf8StringMarshaller.Free(pseudoClasses_p[i]); }
            NativeMemory.Free(pseudoClasses_p);
        }
    }

